import{c as t,Q as o,j as r,m as i}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"别再 prompt agent 了？一周之内，三个最有资格说话的人说了同一句话","description":"","frontmatter":{},"headers":[],"relativePath":"research/tweets/2026-06-09-@cxjwin-355193.md","filePath":"research/tweets/2026-06-09-@cxjwin-355193.md","lastUpdated":1785909234000}'),n={name:"research/tweets/2026-06-09-@cxjwin-355193.md"};function a(l,e,s,p,d,h){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="别再-prompt-agent-了-一周之内-三个最有资格说话的人说了同一句话" tabindex="-1">别再 prompt agent 了？一周之内，三个最有资格说话的人说了同一句话 <a class="header-anchor" href="#别再-prompt-agent-了-一周之内-三个最有资格说话的人说了同一句话" aria-label="Permalink to &quot;别再 prompt agent 了？一周之内，三个最有资格说话的人说了同一句话&quot;">​</a></h1><p><strong>作者</strong>：码良 (@cxjwin)<br><strong>發布時間</strong>：2026-06-09<br><strong>原始連結</strong>：<a href="https://x.com/cxjwin/status/2064492969005355193" target="_blank" rel="noreferrer">https://x.com/cxjwin/status/2064492969005355193</a><br><strong>類型</strong>：Twitter Article（簡體中文）<br><strong>統計</strong>：❤️ 6 · 🔁 0 · 🔖 2 · 👁 737</p><hr><h2 id="分析摘要" tabindex="-1">分析摘要 <a class="header-anchor" href="#分析摘要" aria-label="Permalink to &quot;分析摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：綜合 Steinberger/Cherny/Felix Rieseberg 三人觀點，梳理 prompt→context→harness→loop 四級演進；Felix 的「tasks→responsibilities」升維是最重要的新洞察；附 comprehension debt、overbaking、Ralph Wiggum 等概念的歷史考古。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>四級演進梯子（最可行動框架）</strong>： <ul><li>任務是一句話 → 寫好 prompt</li><li>任務塞不進一次對話 → 管理 context</li><li>任務要跨小時、要驗證、要恢復 → 建 harness</li><li>任務變成「持續發現活、持續干活」→ 寫 loop</li></ul></li><li><strong>Felix Rieseberg 的升維（最重要洞察）</strong>：&quot;Moving from giving AI tasks to giving it responsibilities&quot;——三段論：提問→任務→責任；任務「從人開始，以人結束」；責任「人不在起點，也不在終點」；loop 是手段，responsibility 是本質</li><li><strong>Loop 考古</strong>：Ralph Wiggum loop（Geoffrey Huntley，while true + Stop hook）→ Claude Code 官方插件 → Daniel Demmel 的 Feedback Loop Engineering → Steinberger/Cherny 集中發聲 → Addy Osmani 定名 Loop Engineering；「loop 不是靈光一現，是行業各自重新發明後的收敛」</li><li><strong>兩盆冷水</strong>： <ul><li>harness 沒有過時，loop 消費 harness（驗證器、狀態持久化、可觀測性全在 harness 裡）</li><li>comprehension debt（理解債務）：無人值守 loop 犯的錯誤無人讀，理解債務比技術債務涨得還快</li></ul></li><li><strong>overbaking 失敗模式</strong>：無監控 loop 可能花一整晚重構本來能跑的代碼庫繞過一個環境小錯誤</li></ol><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li>低流量文章（737 views）但合成視角有獨特價值，非其他文章的簡單重複</li><li>Felix Rieseberg 的 &quot;responsibilities not tasks&quot; 框架在其他文章中沒有出現，是本批最獨特洞察之一</li><li>作者明確指出「不是說所有場景都不 prompt 了」——對邊界的清晰態度值得肯定</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>理由</th></tr></thead><tbody><tr><td>A. Workspace 可行動性</td><td>6/10</td><td>四級演進梯子可直接用於任務路由決策；comprehension debt 是可操作的風險提醒</td></tr><tr><td>B. 創新性</td><td>8/10</td><td>Felix 的 tasks→responsibilities 框架、comprehension debt 概念、overbaking 命名是本批獨家內容</td></tr><tr><td>C. 證據品質</td><td>6/10</td><td>引用一手資料（Steinberger/Cherny/Felix 原句）；歷史考古有可驗證時間軸</td></tr><tr><td>D. 技術深度</td><td>5/10</td><td>概念層面為主；harness-is-not-dead 澄清有工程價值</td></tr><tr><td>E. 泛化性</td><td>7/10</td><td>四級演進框架 + responsibility model 可泛化到任何 agent 工程決策</td></tr><tr><td><strong>加權總分</strong></td><td><strong>6.40/10</strong></td><td>A×0.3 + B×0.2 + C×0.2 + D×0.15 + E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule<br><strong>整合位置</strong>：<code>core.md</code>：四級演進梯子（prompt→context→harness→loop）作為任務路由 heuristic；<code>CLAUDE.md</code>：tasks→responsibilities 作為 loop 的本質定義；comprehension debt 入 MEMORY 警告<br><strong>整合狀態</strong>：待實作</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>6 月 7 日，OpenClaw 创始人 Peter Steinberger 发推：</p><blockquote><p>&quot;You shouldn&#39;t be prompting coding agents anymore. You should be designing loops that prompt your agents.&quot;</p></blockquote><p>几乎同时，Claude Code 负责人 Boris Cherny 在 Acquired 播客上说：</p><blockquote><p>&quot;I don&#39;t prompt Claude anymore. I have loops running that prompt Claude and figuring out what to do. My job is to write loops.&quot;</p></blockquote><p>这段剪辑迅速在 X 上刷屏（有转述称 24 小时内近 70 万播放）。</p><p>然后是 6 月 9 日，Claude Fable 5 发布。次日凌晨，Claude Cowork 的工程负责人 Felix Rieseberg 发了条 thread：</p><blockquote><p>&quot;Its job is no longer to help me fix a crash, it&#39;s to keep our apps from crashing.&quot;</p></blockquote><p>三个人、三条产品线（OpenClaw、Claude Code、Claude Cowork）、一周之内、同一个判断。</p><h2 id="接着我之前那条演进线说" tabindex="-1">接着我之前那条演进线说 <a class="header-anchor" href="#接着我之前那条演进线说" aria-label="Permalink to &quot;接着我之前那条演进线说&quot;">​</a></h2><p>我之前写过：prompt engineering → context engineering → harness engineering，这条线背后的驱动力是任务尺寸。现在可以接上第四级了：</p><ul><li>任务是一句话 → 写好 prompt</li><li>任务塞不进一次对话 → 管理 context</li><li>任务要跨小时、要验证、要恢复 → 建 harness</li><li>任务变成&quot;持续发现活、持续干活&quot; → 写 loop</li></ul><p>Addy 给的定义很干净：loop engineering 就是把&quot;负责 prompt agent 的那个人&quot;换掉——你设计一个系统来代替你。loop 是一个递归目标：定义一次目的，AI 迭代直到完成。</p><p>典型形态：定时唤醒 → 读 CI 失败/issues/commits 找活 → 开独立 worktree 派 sub-agent 干活 → 第二个 sub-agent 对照测试做 review → 自动开 PR、更新 ticket → 搞不定的进人工收件箱 → 状态写进文件，明天接着跑。你设计一次。之后每一步，都不需要你 prompt。</p><h2 id="但-loop-不是新发明-是被一步步-收编-的土方法" tabindex="-1">但 loop 不是新发明，是被一步步&quot;收编&quot;的土方法 <a class="header-anchor" href="#但-loop-不是新发明-是被一步步-收编-的土方法" aria-label="Permalink to &quot;但 loop 不是新发明，是被一步步&quot;收编&quot;的土方法&quot;">​</a></h2><ul><li>去年夏天，Geoffrey Huntley 提出 Ralph Wiggum 技术——while true + Stop hook 逼 agent 迭代</li><li>去年 12 月，Anthropic 把 Ralph 做成了 Claude Code 官方插件</li><li>今年 1 月，Daniel Demmel 写了《Feedback Loop Engineering》</li><li>6 月初，Steinberger 和 Cherny 集中发声，Addy 定名</li></ul><p>loop 不是谁的灵光一现，是整个行业把同一个土办法各自重新发明了一遍之后的收敛。</p><h2 id="felix-那半圈才是真正的升维" tabindex="-1">Felix 那半圈才是真正的升维 <a class="header-anchor" href="#felix-那半圈才是真正的升维" aria-label="Permalink to &quot;Felix 那半圈才是真正的升维&quot;">​</a></h2><p>Steinberger 和 Cherny 说的是形态：循环地跑。Felix 说的是性质。他的原话：</p><blockquote><p>&quot;Moving from giving AI tasks to giving it responsibilities.&quot;</p></blockquote><p>他的三段论：第一阶段，提问；第二阶段，任务（每个任务&quot;从人类开始，以人类结束&quot;）；第三阶段，责任（人不在起点，也不在终点）。带过团队的人秒懂这个区别：交代任务要验收每一次；交付责任只看结果指标。loop 是实现手段，责任制才是本质——你不是在给 Claude 派活，你是在给它定 KPI、划地盘。</p><h2 id="两盆冷水" tabindex="-1">两盆冷水 <a class="header-anchor" href="#两盆冷水" aria-label="Permalink to &quot;两盆冷水&quot;">​</a></h2><p><strong>第一盆：&quot;harness 过时了&quot;是误读。</strong> 连定名者自己都没这么说。Addy 的原话是 loop &quot;在 harness 之上一层楼&quot;——还是那个 harness，只是它跑在定时器上、会派生帮手、会自我喂养。loop 是消费 harness 的：验证器、状态持久化、可观测性，这些脏活一件没少，全在 harness 里。</p><p>X 上有条回复说得很精准：agent loop 本质上就是带模糊状态转移的状态机，难的不是 loop 本身，是防止它因为一个无限重试 bug 烧掉 200 刀的 error boundary。</p><p>Huntley 给这个失败模式起过名：<strong>overbaking（烤过头）</strong>。没有监控的 loop，可能花一整晚重构一个本来能跑的代码库，就为了绕过一个环境小错误。</p><p>还有一个值得记住的新债务概念：<strong>comprehension debt（理解债务）</strong>。无人值守的 loop 会犯无人值守的错误，你不读它交付的东西，理解债务比技术债务涨得还快。</p><p><strong>第二盆：token 经济学。</strong> Addy 自己都说：这还很早期，他持怀疑态度，token 富裕和贫穷的人玩法会差得很远。Cherny 的 token 账单不用他自己付。你的归你。</p><h2 id="我的判断" tabindex="-1">我的判断 <a class="header-anchor" href="#我的判断" aria-label="Permalink to &quot;我的判断&quot;">​</a></h2><p>先把边界说清楚：这不是说以后所有场景都不写 prompt 了。一次性问题、探索性任务、低频任务，直接 prompt 仍然是最快的。loop 真正吃的是另一类活——重复、高价值、可验证、可恢复的任务。</p><p>模型每强一代，agent 能独立跑的时长就长一截，抽象单位就往上挪一格。Fable 5 这一代之后，loop 很可能从大佬的玩具，变成普通团队也值得排上日程的工程实践。</p><p>但注意 Demmel 在 1 月写下的那句话——比这波热潮早了四个月：</p><blockquote><p>prompt 和 harness 会随模型演进而变，紧凑反馈回路的价值不会变。就算 AI 泡沫下个月破了，你留下的也是易于测试的代码库。</p></blockquote><p>可观测性、结构化日志、清晰接口、有用的报错——这些在任何人 prompt 任何模型之前，就已经是好的工程实践了。loop engineering 的入场券，还是那套没人爱干的基本功。新词会一直换。基本功不会。</p>',47)])])}const c=t(n,[["render",a]]);export{u as __pageData,c as default};
